import{_ as t,o as e,c as r,a5 as n}from"./chunks/framework.BmD0ICqc.js";const s="/study/images/game/ui-layout-and-interaction.svg",g=JSON.parse('{"title":"ゲームUIの基本 — 表示・配置・操作をつなぐ","description":"","frontmatter":{"title":"ゲームUIの基本 — 表示・配置・操作をつなぐ","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"HP表示とポーズメニューを例に、UI、HUD、Canvas、アンカー、ピボット、画面サイズへの対応、選択と決定の役割を説明する。","aliases":["UI","HUD","ユーザーインターフェース","Canvas","RectTransform","アンカー","ピボット","レイアウト","フォーカス","ナビゲーション","ボタン","uGUI"],"verification":"Unity 6.0向けuGUI 2.0とInput System 1.11の公式資料に照合（2026-11-07）"}},"headers":[],"relativePath":"game/basics/ui-layout-and-interaction.md","filePath":"game/basics/ui-layout-and-interaction.md"}'),o={name:"game/basics/ui-layout-and-interaction.md"};function i(u,a,l,c,d,h){return e(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="ゲームuiの基本-—-表示・配置・操作をつなぐ" tabindex="-1">ゲームUIの基本 — 表示・配置・操作をつなぐ <a class="header-anchor" href="#ゲームuiの基本-—-表示・配置・操作をつなぐ" aria-label="Permalink to &quot;ゲームUIの基本 — 表示・配置・操作をつなぐ&quot;">​</a></h1><p>画面のHP、アイテム一覧、ポーズメニューは、プレイヤーへ情報を伝えたり操作を受け取ったりする<strong>UI（ユーザーインターフェース）<strong>です。プレイ中に重ねて表示するHPや照準などを</strong>HUD</strong>と呼びます。ここではUnity 6.0向けの<strong>uGUI</strong>を例に、画面上の部品と操作を見ます。<a href="https://docs.unity3d.com/Packages/com.unity.ugui@2.0/manual/index.html" target="_blank" rel="noreferrer">UnityのuGUI</a></p><h2 id="表示する情報と、操作する部品" tabindex="-1">表示する情報と、操作する部品 <a class="header-anchor" href="#表示する情報と、操作する部品" aria-label="Permalink to &quot;表示する情報と、操作する部品&quot;">​</a></h2><table tabindex="0"><thead><tr><th>部品の例</th><th>担当すること</th></tr></thead><tbody><tr><td><strong>文字・画像</strong></td><td>HPの数値、アイテムの絵、説明文などを表示する。</td></tr><tr><td><strong>ゲージ</strong></td><td>現在値と最大値の関係などを、長さや塗りつぶしで示す。</td></tr><tr><td><strong>ボタン</strong></td><td>決定操作を受け、再開や購入などの処理へつなぐ。</td></tr><tr><td><strong>パネル・一覧</strong></td><td>関連する表示や操作部品をまとめる。</td></tr></tbody></table><p>例えば現在HPが70、最大HPが100なら、UIはその値を読み、<code>70 / 100</code>の文字や70%のゲージを表示できます。ゲームが管理するHPと、そこから作る表示を対応付け、値が変わったときや画面を開いたときに更新します。<a href="/study/game/basics/game-events-and-notifications.html">ゲーム内イベントと通知</a> · <a href="/study/design/case-studies/ui-notification.html">UI通知の設計例</a></p><h2 id="canvasに置き、表示する場所を決める" tabindex="-1">Canvasに置き、表示する場所を決める <a class="header-anchor" href="#canvasに置き、表示する場所を決める" aria-label="Permalink to &quot;Canvasに置き、表示する場所を決める&quot;">​</a></h2><p>uGUIでは<strong>Canvas</strong>がUIの描画のまとまりになります。<strong>Screen Space - Overlay</strong>は画面上へUIを重ね、<strong>Screen Space - Camera</strong>は指定したカメラで描画します。<strong>World Space</strong>は、ゲーム世界の位置にUIを置きます。例えば画面端のHP表示と、キャラクターの頭上に置く表示では、使う基準が変わります。<a href="https://docs.unity3d.com/Packages/com.unity.ugui@2.0/manual/UICanvas.html" target="_blank" rel="noreferrer">uGUIのCanvasと描画モード</a></p><p>UIの位置と大きさを表す部品が<strong>RectTransform</strong>です。<strong>アンカー</strong>は親の矩形のどの位置を基準にするか、<strong>ピボット</strong>はそのUI自身の回転や拡縮などの基準点を表します。アンカーを左上へまとめ、そこからの余白でHP表示を置けば、親の幅が変わっても左上を基準に配置できます。<a href="https://docs.unity3d.com/Packages/com.unity.ugui@2.0/manual/UIBasicLayout.html" target="_blank" rel="noreferrer">uGUIの基本レイアウト</a></p><figure class="study-figure"><img src="'+s+'" alt="幅の違う二つの画面で、HP表示は左上、ポーズボタンは右上を基準に置く。ゲームのHPから表示を更新し、再開ボタンの操作からゲームへ要求を送る。" width="760" height="470" loading="lazy"><figcaption>上は親の角を基準にする配置、下はゲームのデータとUIの操作の関係です。<a href="/study/images/game/ui-layout-and-interaction.svg" target="_blank" rel="noopener noreferrer">UIの配置と操作の図を拡大</a></figcaption></figure><h2 id="画面の大きさに合わせる" tabindex="-1">画面の大きさに合わせる <a class="header-anchor" href="#画面の大きさに合わせる" aria-label="Permalink to &quot;画面の大きさに合わせる&quot;">​</a></h2><p>画面の解像度や縦横比が変わると、UIを置ける範囲も変わります。<strong>Canvas Scaler</strong>では、UIの大きさを一定のピクセル数にする設定や、基準解像度と画面サイズに応じて拡大・縮小する設定を選べます。アンカーによる配置と、全体の拡大・縮小は別の設定として確認します。<a href="https://docs.unity3d.com/Packages/com.unity.ugui@2.0/manual/script-CanvasScaler.html" target="_blank" rel="noreferrer">Canvas Scaler</a></p><p>ボタンや文章を並べるときは、<strong>レイアウトグループ</strong>などで間隔やサイズを管理できます。横長、縦長、長い翻訳文などの条件で、文字が切れず、押す場所を見分けられるかを確認します。ここでのCanvasやRectTransformはuGUIの仕組みです。Unityの別のUIシステムを使う場合は、その配置と入力の規則を確認します。<a href="https://docs.unity3d.com/Packages/com.unity.ugui@2.0/manual/UIAutoLayout.html" target="_blank" rel="noreferrer">uGUIの自動レイアウト</a></p><h2 id="指す操作と、選んで決定する操作" tabindex="-1">指す操作と、選んで決定する操作 <a class="header-anchor" href="#指す操作と、選んで決定する操作" aria-label="Permalink to &quot;指す操作と、選んで決定する操作&quot;">​</a></h2><p>マウスやタッチは、画面の位置を指定する<strong>ポインター操作</strong>です。キーボードやゲームパッドでは、「いま選択しているボタン」を移し、決定します。操作を受け取る対象を示す考え方を<strong>フォーカス</strong>と呼び、uGUIではEventSystemが管理する現在の選択と、Selectableのナビゲーション設定などを使います。<a href="https://docs.unity3d.com/Packages/com.unity.ugui@2.0/manual/script-SelectableNavigation.html" target="_blank" rel="noreferrer">uGUIの選択移動</a> · <a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/manual/UISupport.html" target="_blank" rel="noreferrer">Input SystemのUI入力</a></p><p>メニューを開いたら最初に何を選ぶか、上下左右でどこへ移るか、戻るとどの画面へ戻るかを決めます。Input SystemとuGUIを組み合わせる構成では、<code>InputSystemUIInputModule</code>がポインターや移動・決定などのアクションをUIへ渡します。<a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/manual/UISupport.html" target="_blank" rel="noreferrer">Input SystemのUI入力モジュール</a></p><h2 id="小さな確認手順" tabindex="-1">小さな確認手順 <a class="header-anchor" href="#小さな確認手順" aria-label="Permalink to &quot;小さな確認手順&quot;">​</a></h2><ol><li>ゲームのHPを変え、文字とゲージが同じ値を表すことを確かめる。</li><li>画面を横長・縦長に変え、HPとメニューの位置、文字の収まりを見る。</li><li>ポインター操作と、方向キー・決定による操作をそれぞれ試し、再開後の表示とゲームの状態を確かめる。</li></ol><h2 id="uiの操作からゲームへ要求する" tabindex="-1">UIの操作からゲームへ要求する <a class="header-anchor" href="#uiの操作からゲームへ要求する" aria-label="Permalink to &quot;UIの操作からゲームへ要求する&quot;">​</a></h2><p>再開ボタンを決定すると、ゲームへ再開を要求し、ゲーム側が状態を切り替えます。その結果をUIに反映すると、表示と操作のつながりを追えます。ポーズ中の操作とプレイ中の移動をどう切り替えるかは、<a href="/study/game/basics/input-actions-and-devices.html">入力アクション</a>と<a href="/study/game/basics/game-states-and-pause.html">ゲームの状態とポーズ</a>へ進みます。</p><p>シーン内の部品としての配置は<a href="/study/game/basics/scenes-and-components.html">シーンとコンポーネント</a>、画面へ映す座標は<a href="/study/graphics/basics/transforms-and-cameras.html">座標変換とカメラ</a>で扱います。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/game/localization-design.html">ローカライズの設計</a></li></ul>',22)])])}const p=t(o,[["render",i]]);export{g as __pageData,p as default};
